const chartHoverTip=document.body.appendChild(Object.assign(document.createElement('div'),{id:'chart-hover-tip'}));let activeChartGraphic;
function positionChartTip(event){const svg=activeChartGraphic?.ownerSVGElement,box=svg?.getBoundingClientRect(),lines=chartHoverTip.dataset.lines||1;if(box&&activeChartGraphic?.hasAttribute('fill-opacity')){chartHoverTip.style.top=`${Math.max(8,box.top+10)}px`;chartHoverTip.style.maxHeight=`${Math.max(80,box.height-20)}px`;chartHoverTip.style.fontSize=`${Math.max(10,Math.min(13,box.height/(Number(lines)*2.8)))}px`;chartHoverTip.style.lineHeight='1.65';chartHoverTip.style.left=`${Math.min(window.innerWidth-380,Math.max(8,event.clientX+14))}px`;return;}const x=Math.min(window.innerWidth-380,event.clientX+16),y=Math.min(window.innerHeight-120,event.clientY+16);chartHoverTip.style.left=`${Math.max(8,x)}px`;chartHoverTip.style.top=`${Math.max(8,y)}px`;chartHoverTip.style.maxHeight='';}
function chartTooltipContent(graphic,text){const lines=text.split('\n').filter(Boolean),svg=graphic.ownerSVGElement,colors=[...svg.querySelectorAll('polyline[stroke]')].map(x=>x.getAttribute('stroke'));chartHoverTip.dataset.lines=lines.length;if(lines.length>2&&colors.length){chartHoverTip.innerHTML=`<b>${esc(lines[0])}</b>${lines.slice(1).map((line,i)=>`<div class="tip-row" style="color:${colors[i%colors.length]}"><span>${esc(line)}</span></div>`).join('')}`;}else chartHoverTip.textContent=text;}
document.addEventListener('pointerover',event=>{const graphic=event.target.closest?.('circle,rect,path');const title=graphic?.querySelector(':scope > title'),text=graphic?.dataset.chartTip||title?.textContent;if(text){if(title){graphic.dataset.chartTip=text;graphic.setAttribute('aria-label',text);title.remove();}activeChartGraphic=graphic;chartTooltipContent(graphic,text);chartHoverTip.style.display='block';positionChartTip(event);}});document.addEventListener('pointermove',event=>{if(activeChartGraphic)positionChartTip(event);});document.addEventListener('pointerout',event=>{if(event.target===activeChartGraphic){activeChartGraphic=null;chartHoverTip.style.display='none';}});
const num=(v,d=0)=>v===null||v===undefined?'—':Number(v).toLocaleString('zh-CN',{maximumFractionDigits:d,minimumFractionDigits:d});
const percent=(v,total)=>v===null||v===undefined||total===null||total===undefined||Number(total)<=0?'—':`${num(Number(v)/Number(total)*100,1)}%`;
