async function render(){const token=++seq,key=state.page;$('#title').textContent=pages[key][1];$('#subtitle').textContent=pages[key][2];$('#crumb').textContent=pages[key][1];document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===key));$('#content').innerHTML='<div class="loading">正在读取真实数据…</div>';$('#refresh').disabled=true;try{const overviewData=await api('overview');if(token!==seq)return;const q=overviewData.quality;$('#source').innerHTML=`<span><span class="live-dot"></span>${esc(q.sourceLabel)}</span><span>PG 读取 ${date(q.pgReadAt)}</span><span>Clerk ${q.clerkStatus==='AVAILABLE'?'已连接 · '+date(q.clerkReadAt):'不可用'}</span>`;let html;if(key==='overview')html=overview(overviewData);else if(key==='events')html=eventsPage(await api('events'));else if(key==='funds')html=funds(await api('funds'));else if(key==='quality')html=quality(await api('quality'));else if(key==='activity'){const a=await api('activity');html=`<div class="cards">${card('周期交易用户',num(a.summary.periodTraders),'所选周期 · 去重用户','activity')}${card('7 日复交易率',a.cohorts[7].eligible?num(a.cohorts[7].returned/a.cohorts[7].eligible*100,1)+'%': '—',`${a.cohorts[7].returned} / ${a.cohorts[7].eligible} 个成熟用户`,'activity')}${card('30 日复交易率',a.cohorts[30].eligible?num(a.cohorts[30].returned/a.cohorts[30].eligible*100,1)+'%':'—',`${a.cohorts[30].returned} / ${a.cohorts[30].eligible} 个成熟用户`,'activity')}</div><section class="panel"><h2>最近 7 日无成交用户</h2>${table(a.quiet,[['id','用户 ID','id'],['lastTrade','最近成交','date']])}</section>`;}else{const d=await api(key);html=pageOverview(key,overviewData.summary)+(key==='agents'?modelAnalytics(d):key==='orders'?matchAnalytics(d):'')+listing(d,key)+(key==='signals'?'<div class="note">当前信号仅支持 BUY / NO_TRADE；共享分析结果见 <button id="analyses-button" class="detail-btn">共享分析明细 ↗</button>。</div>':'');}if(token!==seq)return;$('#content').innerHTML=(q.clerkStatus!=='AVAILABLE'?`<div class="note error">${esc(q.clerkReason)}。注册人数显示为 —，PG 指标仍可使用。</div>`:'')+html;bind();}catch(e){if(token===seq)$('#content').innerHTML=`<div class="note error">${esc(e.message)}。请稍后点击刷新重试。</div>`;}finally{if(token===seq)$('#refresh').disabled=false;}}
function bind(){document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>{$('#detail-content').textContent=JSON.stringify(lastRows[Number(b.dataset.detail)],null,2);$('#detail').showModal();});const search=()=>{state.q=$('#search').value;state.p=1;render();};if($('#search')){$('#search').onkeydown=e=>{if(e.key==='Enter')search();};$('#search-button').onclick=search;}if($('#status'))$('#status').onchange=e=>{state.status=e.target.value;state.p=1;render();};if($('#prev'))$('#prev').onclick=()=>{state.p--;render();};if($('#next'))$('#next').onclick=()=>{state.p++;render();};document.querySelectorAll('[data-fund-tab]').forEach(button=>button.onclick=()=>{state.fundScope=button.dataset.fundTab;render();});if($('#analyses-button'))$('#analyses-button').onclick=async()=>{try{const d=await api('analyses');$('#detail-content').textContent=JSON.stringify(d,null,2);$('#detail').showModal();}catch(e){$('#detail-content').textContent=e.message;$('#detail').showModal();}};}
$('#close-detail').onclick=()=>$('#detail').close();$('#refresh').onclick=render;window.addEventListener('hashchange',()=>{state.page=pages[location.hash.slice(1)]?location.hash.slice(1):'overview';state.p=1;state.q='';state.status='';render();});document.querySelectorAll('[data-range]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-range]').forEach(x=>x.classList.toggle('active',x===b));state.range=b.dataset.range;state.p=1;$('#custom').hidden=state.range!=='custom';if(state.range!=='custom')render();});$('#apply').onclick=render;const headerRight=$('.header-right');headerRight.childNodes.forEach(node=>{if(node.nodeType===Node.TEXT_NODE&&node.textContent.includes('本地工作区'))node.textContent=' 受保护访问 ';});const logout=document.createElement('button');logout.className='button';logout.textContent='退出';logout.onclick=async()=>{try{await fetch('/auth/logout',{method:'POST'});}finally{location.replace('/login');}};headerRight.insertBefore(logout,$('.avatar'));const today=new Date(Date.now()+28800000).toISOString().slice(0,10);$('#from').value=today;$('#to').value=today;state.page=pages[location.hash.slice(1)]?location.hash.slice(1):'overview';render();
